		this.urnsLeft = Math.max(0, Math.min(room.getUrns(), urnsLeft));
		this.chestOpen = chestOpen;
		this.sarcophagusOpen = sarcophagusOpen;
		this.trapDone = trapDone;
	}

	/** The start of a fresh run, outside room one's spear trap. */
