package com.codex.plunder.ui;

import java.awt.Component;
import javax.swing.Timer;

/** Eases a value toward its target on the Swing thread so rings and bars fill instead of jumping. */
final class Animator
{
	private static final int FRAME_MS = 16;
	private static final double EASE = 0.18;

	private final Component owner;
	private final Timer timer;
	private double value;
	private double target;

	Animator(Component owner)
	{
		this.owner = owner;
		this.timer = new Timer(FRAME_MS, e -> step());
	}

	double get()
	{
		return value;
	}

	void set(double newTarget, boolean animate)
	{
		target = newTarget;
		if (!animate || !owner.isShowing())
		{
			value = newTarget;
			timer.stop();
			owner.repaint();
			return;
		}
		if (!timer.isRunning())
		{
			timer.start();
		}
	}

	private void step()
	{
		value += (target - value) * EASE;
		if (Math.abs(target - value) < 0.002 || !owner.isShowing())
		{
			value = target;
			timer.stop();
		}
		owner.repaint();
	}
}

package com.codex.plunder.ui;

import java.awt.Color;
import java.awt.Cursor;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.LayoutManager;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.geom.RoundRectangle2D;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;

/**
 * A rounded, softly lit surface. Optionally clickable, with a hover lift and an
 * accent stripe down the left edge.
 */
public class Card extends JPanel
{
	private Color accent;
	private boolean hover;
	private boolean highlighted;
	private Runnable onClick;

	public Card(LayoutManager layout)
	{
		super(layout);
		setOpaque(false);
		setBorder(new EmptyBorder(8, 10, 8, 10));
	}

	public Card accent(Color color)
	{
		accent = color;
		repaint();
		return this;
	}

	/** A brighter rim for the card that matters most on screen. */
	public Card highlighted(boolean value)
	{
		highlighted = value;
		repaint();
		return this;
	}

	public Card onClick(Runnable action)
	{
		onClick = action;
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		MouseAdapter adapter = new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				hover = true;
				repaint();
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				// Children forward their events here, so only clear hover when the pointer has really left.
				if (!contains(SwingUtilities.convertPoint(e.getComponent(), e.getPoint(), Card.this)))
				{
					hover = false;
					repaint();
				}
			}

			@Override
			public void mouseReleased(MouseEvent e)
			{
				if (SwingUtilities.isLeftMouseButton(e) && onClick != null
					&& contains(SwingUtilities.convertPoint(e.getComponent(), e.getPoint(), Card.this)))
				{
					onClick.run();
				}
			}
		};
		addMouseListener(adapter);
		Ui.forwardMouse(this, adapter);
		return this;
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		RoundRectangle2D shape = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1, h - 1, Theme.RADIUS, Theme.RADIUS);

		Color top = hover ? Theme.CARD_HOVER : Theme.CARD_TOP;
		Color bottom = hover ? Theme.mix(Theme.CARD_HOVER, Theme.CARD, 0.5) : Theme.CARD;
		g.setPaint(new GradientPaint(0, 0, top, 0, h, bottom));
		g.fill(shape);

		if (accent != null)
		{
			g.setClip(shape);
			g.setPaint(new GradientPaint(0, 0, accent, 0, h, Theme.alpha(accent, 90)));
			g.fillRect(0, 0, 3, h);
			g.setClip(null);
		}

		Color rim = highlighted ? Theme.alpha(Theme.GOLD, 150) : hover ? Theme.alpha(Theme.GOLD, 90) : Theme.STROKE_SOFT;
		g.setColor(rim);
		g.draw(shape);

		// A one pixel sheen along the top edge, like light on vellum.
		g.setColor(Theme.alpha(Color.WHITE, hover ? 22 : 12));
		g.drawLine(Theme.RADIUS / 2, 1, w - Theme.RADIUS / 2, 1);
		g.dispose();
		super.paintComponent(graphics);
	}
}

package com.codex.plunder.ui;

import com.codex.plunder.core.Check;
import java.awt.BasicStroke;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Path2D;
import javax.swing.JComponent;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;

/** One line of the ready check: a teal tick for a pass, an ember mark for a warning, a gold dot for a tip. */
class CheckRow extends JPanel
{
	CheckRow(Check check, int width)
	{
		super(new BorderLayout(8, 0));
		setOpaque(false);
		setBorder(new EmptyBorder(2, 0, 2, 0));
		Color color = color(check.getState());
		add(new Mark(check.getState(), color), BorderLayout.WEST);
		JPanel words = new JPanel(new BorderLayout(0, 1));
		words.setOpaque(false);
		words.add(Ui.label(check.getTitle(), Theme.body(), check.getState() == Check.State.WARN ? color : Theme.TEXT), BorderLayout.NORTH);
		words.add(Ui.wrapped(check.getDetail(), Theme.small(), Theme.TEXT_FAINT, width - 22), BorderLayout.CENTER);
		add(words, BorderLayout.CENTER);
	}

	static Color color(Check.State state)
	{
		switch (state)
		{
			case GOOD:
				return Theme.TEAL;
			case WARN:
				return Theme.EMBER;
			default:
				return Theme.GOLD;
		}
	}

	private static final class Mark extends JComponent
	{
		private final Check.State state;
		private final Color color;

		Mark(Check.State state, Color color)
		{
			this.state = state;
			this.color = color;
			setPreferredSize(new Dimension(16, 16));
		}

		@Override
		protected void paintComponent(Graphics graphics)
		{
			Graphics2D g = (Graphics2D) graphics.create();
			Theme.smooth(g);
			int d = 14;
			int x = 1;
			int y = 2;
			g.setColor(Theme.alpha(color, 40));
			g.fill(new Ellipse2D.Float(x, y, d, d));
			g.setColor(color);
			g.setStroke(new BasicStroke(1.2f));
			g.draw(new Ellipse2D.Float(x + 0.5f, y + 0.5f, d - 1, d - 1));
			g.setStroke(new BasicStroke(1.6f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			switch (state)
			{
				case GOOD:
					Path2D tick = new Path2D.Float();
					tick.moveTo(x + 4, y + 7.5f);
					tick.lineTo(x + 6.2f, y + 9.8f);
					tick.lineTo(x + 10.2f, y + 4.6f);
					g.draw(tick);
					break;
				case WARN:
					g.drawLine(x + 7, y + 3, x + 7, y + 8);
					g.fillRect(x + 6, y + 10, 2, 2);
					break;
				default:
					g.fill(new Ellipse2D.Float(x + 5, y + 5, 4, 4));
					break;
			}
			g.dispose();
		}
	}
}

package com.codex.plunder.ui;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RadialGradientPaint;
import java.awt.RenderingHints;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Path2D;
import java.awt.image.BufferedImage;
import javax.swing.JComponent;

/**
 * The crest at the top of the panel: the Pilot's medallion, one figure in large gilt numerals
 * (the clock during a run, the deepest room before one), and a line saying what it means.
 * During a run a thin bar under it drains with the clock.
 */
public class Crest extends JComponent
{
	private static final int HEIGHT = 104;

	private final Animator bar = new Animator(this);
	private String heading = "PYRAMID PLUNDER";
	private String figure = "-";
	private String unit;
	private String status = "Log in to plan your runs";
	private Color statusColor = Theme.TEXT_MUTED;
	private Color figureTint = Theme.GOLD_DIM;
	private double progress = -1;

	public Crest()
	{
		setOpaque(false);
		setPreferredSize(new Dimension(10, HEIGHT));
		setMinimumSize(new Dimension(10, HEIGHT));
	}

	/**
	 * @param figure the large figure, such as "3:12" or "8"
	 * @param unit a small word after the figure, or null
	 * @param progress how much of the bar is lit, 0 to 1, or below 0 for no bar
	 */
	public void update(String heading, String figure, String unit, String status, Color statusColor, Color tint, double progress)
	{
		this.heading = heading;
		this.figure = figure;
		this.unit = unit;
		this.status = status;
		this.statusColor = statusColor;
		this.figureTint = tint;
		boolean had = this.progress >= 0;
		this.progress = progress;
		if (progress >= 0)
		{
			bar.set(progress, had);
		}
		repaint();
	}

	/**
	 * Draws text at twice the size of the game's bold font by doubling every pixel, the way the
	 * game itself draws large numbers, so the figures stay crisp instead of being re-rasterised.
	 *
	 * @return the width drawn
	 */
	static int paintLarge(Graphics2D g, String text, int x, int y, Color tint)
	{
		Font font = Theme.title();
		FontMetrics fm = g.getFontMetrics(font);
		int w = Math.max(1, fm.stringWidth(text) + 1);
		int h = fm.getHeight() + 1;
		BufferedImage small = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
		Graphics2D sg = small.createGraphics();
		sg.setFont(font);
		sg.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
		int base = fm.getAscent();
		sg.setColor(Color.BLACK);
		sg.drawString(text, 1, base + 1);
		sg.setPaint(new GradientPaint(0, base - fm.getAscent() + 3, Theme.mix(tint, Color.WHITE, 0.35), 0, base, tint));
		sg.drawString(text, 0, base);
		sg.dispose();
		Graphics2D lg = (Graphics2D) g.create();
		lg.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
		lg.drawImage(small, x, y - 2 * fm.getAscent() + 22, w * 2, h * 2, null);
		lg.dispose();
		return w * 2;
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		g.setPaint(new GradientPaint(0, 0, Theme.mix(Theme.INK, Theme.GOLD_DIM, 0.22), 0, h, Theme.INK));
		g.fillRect(0, 0, w, h);

		// The medallion: a gilt ring with the mark inside, lit from above.
		int mx = 10;
		int my = 14;
		int md = 54;
		g.setPaint(new RadialGradientPaint(mx + md / 2f, my + md / 3f, md * 0.7f, new float[]{0, 1},
			new Color[]{Theme.mix(Theme.CARD_TOP, Theme.GOLD_DIM, 0.35), Theme.INK_DEEP}));
		g.fill(new Ellipse2D.Float(mx, my, md, md));
		g.setStroke(new BasicStroke(2f));
		g.setPaint(new GradientPaint(mx, my, Theme.GOLD_BRIGHT, mx, my + md, Theme.GOLD_DIM));
		g.draw(new Ellipse2D.Float(mx + 1, my + 1, md - 2, md - 2));
		g.setStroke(new BasicStroke(1f));
		g.setColor(Theme.alpha(Theme.GOLD, 70));
		g.draw(new Ellipse2D.Float(mx + 5, my + 5, md - 10, md - 10));
		Sigil.paint(g, mx + 11, my + 11, md - 22);

		int tx = mx + md + 12;
		int room = w - tx - 8;
		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		g.setColor(Theme.TEXT_MUTED);
		g.drawString(Ui.clip(heading, small, room), tx, 22);

		int top = 27;
		int figureW = paintLarge(g, figure, tx, top, figureTint);
		if (unit != null)
		{
			g.setFont(Theme.small());
			g.setColor(Theme.GOLD_DIM);
			g.drawString(unit, tx + figureW + 3, top + 18);
		}
		int cy = top + 50;
		g.setFont(Theme.small());
		if (status != null)
		{
			Ui.shadowed(g, Ui.clip(status, small, room), tx, cy, statusColor);
		}
		if (progress >= 0)
		{
			int by = cy + 8;
			int bw = room;
			g.setColor(Theme.INK_DEEP);
			g.fillRoundRect(tx, by, bw, 4, 4, 4);
			int lit = (int) Math.round(bw * Math.max(0, Math.min(1, bar.get())));
			if (lit > 0)
			{
				g.setPaint(new GradientPaint(tx, 0, Theme.mix(figureTint, Theme.INK, 0.35), tx + bw, 0, figureTint));
				g.fillRoundRect(tx, by, lit, 4, 4, 4);
			}
		}

		// The gilt rule under the crest, with a diamond at its middle.
		int y = h - 2;
		g.setPaint(new GradientPaint(0, 0, Theme.alpha(Theme.GOLD, 0), w / 2f, 0, Theme.alpha(Theme.GOLD, 150), true));
		g.drawLine(0, y, w, y);
		Path2D diamond = new Path2D.Float();
		diamond.moveTo(w / 2f, y - 3);
		diamond.lineTo(w / 2f + 3, y);
		diamond.lineTo(w / 2f, y + 3);
		diamond.lineTo(w / 2f - 3, y);
		diamond.closePath();
		g.setColor(Theme.GOLD);
		g.fill(diamond);
		g.dispose();
	}
}

package com.codex.plunder.ui;

import java.time.Instant;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.Locale;

/** Experience, coins, odds, the clock and dates in the short forms the panel uses. */
public final class Format
{
	private static final DateTimeFormatter CLOCK = DateTimeFormatter.ofPattern("HH:mm", Locale.ENGLISH);
	private static final DateTimeFormatter DAY = DateTimeFormatter.ofPattern("EEE d MMM", Locale.ENGLISH);
	private static final DateTimeFormatter DATE = DateTimeFormatter.ofPattern("EEEE d MMMM yyyy", Locale.ENGLISH);
	private static final DateTimeFormatter SHORT = DateTimeFormatter.ofPattern("d MMM", Locale.ENGLISH);
	private static final DateTimeFormatter MONTH = DateTimeFormatter.ofPattern("MMM yy", Locale.ENGLISH);

	private Format()
	{
	}

	/** "8,240", "41.2k", "412k", "1.24M". */
	public static String amount(long n)
	{
		if (n < 10_000)
		{
			return String.format(Locale.ENGLISH, "%,d", n);
		}
		if (n < 100_000)
		{
			return trim(n / 1_000.0, 1) + "k";
		}
		if (n < 1_000_000)
		{
			return Math.round(n / 1_000.0) + "k";
		}
		if (n < 10_000_000)
		{
			return trim(n / 1_000_000.0, 2) + "M";
		}
		if (n < 1_000_000_000)
		{
			return trim(n / 1_000_000.0, 1) + "M";
		}
		return trim(n / 1_000_000_000.0, 2) + "B";
	}

	/** Coins in the short form, negative amounts with a minus: "812.4M", "-45.2k". */
	public static String coins(long gp)
	{
		return gp < 0 ? "-" + amount(-gp) : amount(gp);
	}

	/** A change with its sign: "+3.2M", "-412k", "0". */
	public static String signed(long gp)
	{
		return gp > 0 ? "+" + amount(gp) : gp < 0 ? "-" + amount(-gp) : "0";
	}

	/** A quantity change with its sign, written in full: "+1,240", "-6". */
	public static String count(long n)
	{
		return (n > 0 ? "+" : n < 0 ? "-" : "") + String.format(Locale.ENGLISH, "%,d", Math.abs(n));
	}

	/** Game ticks as a clock: "4:58", "0:07". */
	public static String clock(int ticks)
	{
		int seconds = (int) Math.round(Math.max(0, ticks) * 0.6);
		return seconds / 60 + ":" + String.format(Locale.ENGLISH, "%02d", seconds % 60);
	}

	/** A chance as odds: "1 in 69", "1 in 4,200", or "none". */
	public static String oneIn(double chance)
	{
		if (chance <= 0)
		{
			return "none";
		}
		return "1 in " + String.format(Locale.ENGLISH, "%,d", Math.round(1 / chance));
	}

	/** A share as a whole percent, or "<1%". */
	public static String percent(double share)
	{
		if (share > 0 && share < 0.01)
		{
			return "<1%";
		}
		return Math.round(share * 100) + "%";
	}

	/** "just now", "12m ago", "3h ago", "2d ago". */
	public static String ago(long ms)
	{
		long minutes = Math.max(0, ms) / 60_000;
		if (minutes < 1)
		{
			return "just now";
		}
		if (minutes < 60)
		{
			return minutes + "m ago";
		}
		if (minutes < 48 * 60)
		{
			return minutes / 60 + "h ago";
		}
		return minutes / (24 * 60) + "d ago";
	}

	private static String trim(double value, int places)
	{
		String text = String.format(Locale.ENGLISH, "%." + places + "f", value);
		while (text.contains(".") && (text.endsWith("0") || text.endsWith(".")))
		{
			text = text.substring(0, text.length() - 1);
		}
		return text;
	}

	/** "2h 14m", "38m", "under a minute". */
	public static String duration(long ms)
	{
		long minutes = ms / 60_000;
		if (minutes < 1)
		{
			return "under a minute";
		}
		if (minutes < 60)
		{
			return minutes + "m";
		}
		return minutes / 60 + "h " + minutes % 60 + "m";
	}

	/** "14:02" in the player's own time. */
	public static String time(long epochMs)
	{
		return CLOCK.format(Instant.ofEpochMilli(epochMs).atZone(ZoneId.systemDefault()));
	}

	/** "Thu 16 Oct". */
	public static String day(long epochMs)
	{
		return DAY.format(Instant.ofEpochMilli(epochMs).atZone(ZoneId.systemDefault()));
	}

	/** "16 Oct". */
	public static String shortDay(long epochMs)
	{
		return SHORT.format(Instant.ofEpochMilli(epochMs).atZone(ZoneId.systemDefault()));
	}

	/** "Oct 26". */
	public static String month(long epochMs)
	{
		return MONTH.format(Instant.ofEpochMilli(epochMs).atZone(ZoneId.systemDefault()));
	}

	/** "Thursday 16 October 2026". */
	public static String date(long epochMs)
	{
		return DATE.format(Instant.ofEpochMilli(epochMs).atZone(ZoneId.systemDefault()));
	}
}

package com.codex.plunder.ui;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.RoundRectangle2D;
import javax.swing.JComponent;

/** A labelled gauge: a sunken channel filled toward a share, with an optional tick mark. */
class Meter extends JComponent
{
	private final Animator fill = new Animator(this);
	private final String label;
	private final String value;
	private final Color color;
	private final double mark;

	/** @param mark a share to mark on the channel, or below 0 for none */
	Meter(String label, String value, double share, Color color, double mark)
	{
		this.label = label;
		this.value = value;
		this.color = color;
		this.mark = mark;
		setOpaque(false);
		setPreferredSize(new Dimension(10, 30));
		fill.set(Math.max(0, Math.min(1, share)), false);
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		g.setColor(Theme.TEXT_MUTED);
		g.drawString(Ui.clip(label, small, w - small.stringWidth(value) - 8), 0, small.getAscent());
		g.setColor(color);
		g.drawString(value, w - small.stringWidth(value), small.getAscent());

		int y = small.getHeight() + 4;
		RoundRectangle2D channel = new RoundRectangle2D.Float(0.5f, y + 0.5f, w - 1, 7, 7, 7);
		g.setColor(Theme.INK_DEEP);
		g.fill(channel);
		g.setColor(Theme.STROKE_SOFT);
		g.draw(channel);
		int lit = (int) Math.round((w - 2) * fill.get());
		if (lit > 0)
		{
			g.setPaint(new GradientPaint(0, 0, Theme.mix(color, Theme.INK, 0.4), w, 0, color));
			g.fillRoundRect(1, y + 1, lit, 6, 6, 6);
		}
		if (mark >= 0 && mark <= 1)
		{
			int mx = (int) Math.round(1 + (w - 3) * mark);
			g.setColor(Theme.TEXT);
			g.fillRect(mx, y - 1, 1, 10);
		}
		g.dispose();
	}
}

package com.codex.plunder.ui;

import com.codex.plunder.core.Check;
import com.codex.plunder.core.Goal;
import com.codex.plunder.core.Levels;
import com.codex.plunder.core.Odds;
import com.codex.plunder.core.Pace;
import com.codex.plunder.core.Plan;
import com.codex.plunder.core.Planner;
import com.codex.plunder.core.Room;
import com.codex.plunder.core.Run;
import com.codex.plunder.core.Step;
import java.awt.BorderLayout;
import java.awt.CardLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.GridLayout;
import java.util.Locale;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.ScrollPaneConstants;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.PluginPanel;

/**
 * The Plunder Pilot side panel: the crest with the clock or the deepest room, then three pages.
 * Pilot is the next step and the route room by room, Odds is the sceptre and how dry the
 * player has been, and Runs is the rate, the way to a goal level and every run so far.
 */
public class PilotPanel extends PluginPanel
{
	static final int WIDTH = 200;
	private static final String[] TABS = {"pilot", "odds", "runs"};
	private static final int RECENT = 8;

	private final Actions actions;
	private final Crest crest = new Crest();
	private final Segmented tabs = new Segmented(true, "Pilot", "Odds", "Runs");
	private final Segmented goal = new Segmented(false, Goal.EXPERIENCE.getLabel(), Goal.SCEPTRE.getLabel());
	private final CardLayout cards = new CardLayout();
	private final JPanel content = new JPanel(cards);
	private final JScrollPane pilot = scroller();
	private final JScrollPane odds = scroller();
	private final JScrollPane runs = scroller();

	private View view = View.loggedOut();

	public PilotPanel(Actions actions)
	{
		super(false);
		this.actions = actions;
		setLayout(new BorderLayout());
		setBackground(Theme.INK);

		JPanel north = new JPanel(new BorderLayout());
		north.setOpaque(false);
		north.add(crest, BorderLayout.NORTH);
		JPanel tabHolder = new JPanel(new BorderLayout());
		tabHolder.setOpaque(false);
		tabHolder.setBorder(new EmptyBorder(8, 8, 2, 8));
		tabHolder.add(tabs, BorderLayout.CENTER);
		north.add(tabHolder, BorderLayout.SOUTH);
		add(north, BorderLayout.NORTH);

		content.setOpaque(false);
		content.add(pilot, TABS[0]);
		content.add(odds, TABS[1]);
		content.add(runs, TABS[2]);
		add(content, BorderLayout.CENTER);

		tabs.onChange(this::showTab);
		goal.onChange(i -> actions.goal(Goal.values()[i]));
		rebuild();
	}

	private static JScrollPane scroller()
	{
		JScrollPane scroll = new JScrollPane();
		scroll.setBorder(null);
		scroll.setOpaque(false);
		scroll.getViewport().setOpaque(false);
		scroll.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		scroll.getVerticalScrollBar().setUnitIncrement(16);
		scroll.getVerticalScrollBar().setPreferredSize(new Dimension(8, 0));
		return scroll;
	}

	/** Called on the Swing thread whenever anything shown changes. */
	public void update(View view)
	{
		this.view = view;
		goal.setSelected(view.goal.ordinal(), false);
		updateCrest();
		rebuild();
	}

	/** Opens one tab, for previews and tests. */
	public void showTab(int index)
	{
		tabs.setSelected(index, false);
		cards.show(content, TABS[index]);
	}

	private void updateCrest()
	{
		switch (view.state)
		{
			case LOGGED_OUT:
				crest.update("PYRAMID PLUNDER", "-", null, "Log in to plan your runs", Theme.TEXT_MUTED, Theme.GOLD_DIM, -1);
				return;
			case TOO_LOW:
				crest.update("THIEVING " + view.level, "21", "to enter", "The pyramid opens at Thieving 21", Theme.TEXT_MUTED, Theme.GOLD_DIM, -1);
				return;
			default:
				break;
		}
		Plan plan = view.plan;
		if (view.inRun())
		{
			Plan.Stop stop = plan.current();
			int ticks = view.live.ticksLeft;
			Color tint = Theme.clock(ticks);
			crest.update("ROOM " + stop.getRoom().getNumber() + " OF " + plan.getTop().getNumber(), Format.clock(ticks), "left",
				view.step.getTitle(), ticks <= 150 ? tint : Theme.mix(Theme.TEXT_MUTED, Theme.GOLD, 0.45), tint,
				ticks / (double) Planner.RUN_TICKS);
			return;
		}
		Plan fresh = view.fresh;
		crest.update("THIEVING " + view.level + "  -  " + view.goal.getLabel().toUpperCase(Locale.ENGLISH),
			String.valueOf(fresh.getTop().getNumber()), fresh.getTop().getNumber() == 1 ? "room" : "rooms",
			Format.amount(fresh.xpPerHour(Planner.RESTART_TICKS)) + " xp/hr  -  sceptre " + Format.oneIn(fresh.getSceptreChance()),
			Theme.mix(Theme.TEXT_MUTED, Theme.GOLD, 0.35), Theme.GOLD, -1);
	}

	private void rebuild()
	{
		rebuildPilot();
		rebuildOdds();
		rebuildRuns();
	}

	private boolean waiting(StackPanel stack)
	{
		if (view.state == View.State.LOGGED_OUT)
		{
			stack.add(note("The pyramid is sealed", "Log in and the Pilot plans every Pyramid Plunder run for your Thieving level: which rooms to walk through, which urns, chests and sarcophagi are worth the clock, and your odds of the Pharaoh's sceptre."));
			return true;
		}
		if (view.state == View.State.TOO_LOW)
		{
			int left = Levels.xpFor(Room.ENTRY_LEVEL) - (int) Math.min(Integer.MAX_VALUE, view.xp);
			stack.add(note("Not yet", "Pyramid Plunder needs Thieving 21, and the level cannot be boosted. You are " + Format.amount(Math.max(0, left)) + " experience away."));
			return true;
		}
		return false;
	}

	// The Pilot tab.

	private void rebuildPilot()
	{
		StackPanel stack = new StackPanel(8, 8);
		if (waiting(stack))
		{
			replace(pilot, stack);
			return;
		}
		stack.add(new SectionHeader("Run for", view.inRun() ? "replanned every tick" : null));
		stack.add(goal);

		Card next = new Card(new BorderLayout(0, 4));
		boolean danger = view.step.getKind() == Step.Kind.DANGER;
		next.accent(danger ? Theme.BLOOD : view.inRun() ? Theme.clock(view.live.ticksLeft) : Theme.TEAL).highlighted(view.inRun());
		next.add(Ui.label(danger ? "FIRST" : view.inRun() ? "NEXT" : "BEFORE YOU GO IN", Theme.small(), Theme.TEXT_FAINT), BorderLayout.NORTH);
		JPanel words = new JPanel(new BorderLayout(0, 2));
		words.setOpaque(false);
		words.add(Ui.label(view.step.getTitle(), Theme.title(), danger ? Theme.BLOOD : Theme.GOLD_BRIGHT), BorderLayout.NORTH);
		words.add(Ui.wrapped(view.step.getDetail(), Theme.small(), Theme.TEXT_MUTED, WIDTH - 30), BorderLayout.CENTER);
		next.add(words, BorderLayout.CENTER);
		stack.add(next);

		if (!view.inRun() && view.ready != null)
		{
			stack.add(new SectionHeader("Ready check"));
			Card ready = new Card(new BorderLayout());
			StackPanel checks = new StackPanel(4, 0);
			for (Check check : view.ready.checks)
			{
				checks.add(new CheckRow(check, WIDTH - 30));
			}
			ready.add(checks, BorderLayout.CENTER);
			stack.add(ready);
			if (view.ready.artefacts > 0)
			{
				stack.add(Ui.wrapped("Carrying " + view.ready.artefacts + (view.ready.artefacts == 1 ? " artefact" : " artefacts") + " worth "
					+ Format.coins(view.ready.artefactValue) + " gp. They sell for about the same at the Grand Exchange.", Theme.small(), Theme.GOLD_DIM, WIDTH - 16));
			}
		}

		Plan plan = view.plan;
		JPanel tiles = new JPanel(new GridLayout(1, 2, 6, 0));
		tiles.setOpaque(false);
		if (view.inRun())
		{
			tiles.add(new StatTile("+" + Format.amount(view.live.thievingXp), "This run",
				"+" + Format.amount(plan.getThievingXp()) + " to come", Theme.GOLD));
			double chance = 1 - (1 - view.live.sceptreSoFar) * (1 - plan.getSceptreChance());
			tiles.add(new StatTile(Format.oneIn(chance), "Sceptre", view.live.opened + " opened so far", Theme.TEAL));
		}
		else
		{
			tiles.add(new StatTile(Format.amount(plan.getThievingXp()), "Per run",
				plan.getStrengthXp() > 0 ? "+" + Format.amount(plan.getStrengthXp()) + " strength" : "thieving xp", Theme.GOLD));
			tiles.add(new StatTile(Format.oneIn(plan.getSceptreChance()), "Sceptre", "a run", Theme.TEAL));
		}
		stack.add(tiles);

		stack.add(new SectionHeader("Route", "room " + plan.current().getRoom().getNumber() + " to " + plan.getTop().getNumber()));
		Card route = new Card(new BorderLayout());
		StackPanel rows = new StackPanel(0, 0);
		for (Plan.Stop stop : plan.getStops())
		{
			rows.add(new RoomRow(stop, view.inRun() && stop == plan.current()));
		}
		for (int i = plan.getTop().ordinal() + 1; i < Room.values().length; i++)
		{
			rows.add(new RoomRow(Room.values()[i]));
		}
		route.add(rows, BorderLayout.CENTER);
		stack.add(route);
		String foot = view.record.paceSamples >= Pace.TRUSTED
			? "Paced from your own searches. Chests and sarcophagi last in each room, so a swarm or mummy has the least time to chase."
			: "Paced at typical speeds until a few of your runs are timed. Chests and sarcophagi last in each room.";
		stack.add(Ui.wrapped(foot, Theme.small(), Theme.TEXT_FAINT, WIDTH - 16));
		replace(pilot, stack);
	}

	// The Odds tab.

	private void rebuildOdds()
	{
		StackPanel stack = new StackPanel(8, 8);
		if (waiting(stack))
		{
			replace(odds, stack);
			return;
		}
		View.Record r = view.record;
		long opened = 0;
		for (long o : r.opened)
		{
			opened += o;
		}
		double expected = Odds.expected(r.opened);
		JPanel tiles = new JPanel(new GridLayout(1, 2, 6, 0));
		tiles.setOpaque(false);
		tiles.add(new StatTile(String.format(Locale.ENGLISH, "%,d", opened), "Opened", "chests & sarcs", Theme.GOLD));
		tiles.add(new StatTile(String.format(Locale.ENGLISH, "%.2f", expected), "Expected", r.sceptres + (r.sceptres == 1 ? " sceptre found" : " sceptres found"),
			r.sceptres > 0 ? Theme.TEAL : Theme.TEXT_MUTED));
		stack.add(tiles);

		Card luck = new Card(new BorderLayout(0, 6));
		luck.accent(Theme.TEAL);
		if (opened == 0)
		{
			luck.add(Ui.label("No openings yet", Theme.body(), Theme.GOLD), BorderLayout.NORTH);
			luck.add(Ui.wrapped("Every grand gold chest and sarcophagus you open is counted by room, and your sceptre luck is measured against it.",
				Theme.small(), Theme.TEXT_MUTED, WIDTH - 30), BorderLayout.CENTER);
		}
		else
		{
			double share = Odds.luck(r.opened, r.sceptres);
			String verdict;
			Color color;
			if (r.sceptres == 0)
			{
				double had = Odds.atLeastOne(r.opened);
				verdict = Format.percent(had) + " would have one by now";
				color = had > 0.5 ? Theme.EMBER : Theme.GOLD;
			}
			else if (share >= 0.5)
			{
				verdict = "Luckier than " + Format.percent(share);
				color = Theme.TEAL;
			}
			else
			{
				verdict = "Drier than " + Format.percent(1 - share);
				color = Theme.EMBER;
			}
			luck.add(Ui.label(verdict, Theme.body(), color), BorderLayout.NORTH);
			luck.add(new Meter("Your luck", Format.percent(share), share, color, 0.5), BorderLayout.CENTER);
		}
		stack.add(luck);

		Plan fresh = view.fresh;
		double perRun = fresh.getSceptreChance();
		stack.add(new SectionHeader("Your runs", view.goal.getLabel()));
		Card forecast = new Card(new BorderLayout(0, 6));
		StackPanel lines = new StackPanel(4, 0);
		lines.add(line("Each run", Format.oneIn(perRun), Theme.TEAL));
		lines.add(line("Even odds", Format.amount(Odds.runsFor(perRun, 0.5)) + " runs", Theme.GOLD));
		lines.add(line("Nine in ten", Format.amount(Odds.runsFor(perRun, 0.9)) + " runs", Theme.GOLD));
		lines.add(line("In an hour", Format.percent(fresh.sceptrePerHour(Planner.RESTART_TICKS)), Theme.GOLD));
		forecast.add(lines, BorderLayout.CENTER);
		stack.add(forecast);
		if (view.goal == Goal.EXPERIENCE)
		{
			stack.add(Ui.wrapped("Hunting the sceptre opens every chest and the sarcophagi from room 4 on, at some cost in experience. Switch the goal on the Pilot page to compare.",
				Theme.small(), Theme.TEXT_FAINT, WIDTH - 16));
		}

		stack.add(new SectionHeader("Per opening", "chest or sarc"));
		Card rooms = new Card(new BorderLayout());
		StackPanel rows = new StackPanel(3, 0);
		for (Room room : Room.values())
		{
			boolean open = view.level >= room.getLevel();
			long n = r.opened[room.ordinal()];
			rows.add(line("Room " + room.getNumber() + (n > 0 ? "  -  " + Format.amount(n) + " opened" : ""),
				"1 in " + String.format(Locale.ENGLISH, "%,d", room.getSceptreOneIn()), open ? Theme.TEAL : Theme.TEXT_FAINT));
		}
		rooms.add(rows, BorderLayout.CENTER);
		stack.add(rooms);
		stack.add(Ui.wrapped("Finding the sceptre ejects you from the pyramid at once. Rates are the game's, per the Old School wiki.",
			Theme.small(), Theme.TEXT_FAINT, WIDTH - 16));
		replace(odds, stack);
	}

	// The Runs tab.

	private void rebuildRuns()
	{
		StackPanel stack = new StackPanel(8, 8);
		if (waiting(stack))
		{
			replace(runs, stack);
			return;
		}
		View.Record r = view.record;
		Plan fresh = view.fresh;
		int forecast = fresh.xpPerHour(Planner.RESTART_TICKS);
		int rate = r.recentRate > 0 ? r.recentRate : forecast;
		JPanel tiles = new JPanel(new GridLayout(1, 2, 6, 0));
		tiles.setOpaque(false);
		tiles.add(new StatTile(Format.amount(rate), "Xp an hour", r.recentRate > 0 ? "your last runs" : "forecast", Theme.GOLD));
		tiles.add(new StatTile(Format.amount(r.totalRuns), "Runs", Format.coins(r.totalArtefacts) + " gp loot", Theme.TEAL));
		stack.add(tiles);

		int target = Math.max(view.level + 1, Math.min(99, view.targetLevel));
		if (view.level < 99)
		{
			long goalXp = Levels.xpFor(target);
			long left = Math.max(0, goalXp - view.xp);
			int perRun = Math.max(1, fresh.getThievingXp());
			long runsLeft = (left + perRun - 1) / perRun;
			long start = Levels.xpFor(view.level);
			double share = goalXp <= start ? 1 : (view.xp - start) / (double) (goalXp - start);
			Card goalCard = new Card(new BorderLayout(0, 6));
			goalCard.accent(Theme.GOLD);
			goalCard.add(Ui.label("Thieving " + target, Theme.body(), Theme.GOLD), BorderLayout.NORTH);
			String hours = Format.duration(Math.round(left * 3_600_000.0 / Math.max(1, rate)));
			goalCard.add(new Meter(Format.amount(left) + " xp, about " + Format.amount(runsLeft) + " runs", hours, share, Theme.GOLD, -1), BorderLayout.CENTER);
			int unlock = Room.nextUnlock(view.level);
			if (unlock > 0 && unlock < target)
			{
				long toUnlock = Math.max(0, Levels.xpFor(unlock) - view.xp);
				goalCard.add(Ui.wrapped("Room " + Room.highest(unlock).getNumber() + " opens at " + unlock + ", " + Format.amount(toUnlock)
					+ " xp away, and every run after pays more.", Theme.small(), Theme.TEXT_MUTED, WIDTH - 30), BorderLayout.SOUTH);
			}
			stack.add(goalCard);
		}

		stack.add(new SectionHeader("The ladder", "xp an hour"));
		Card ladder = new Card(new BorderLayout());
		StackPanel rows = new StackPanel(3, 0);
		Room mine = Room.highest(view.level);
		for (Plan p : view.ladder)
		{
			Room top = p.getTop();
			boolean yours = top == mine;
			rows.add(line((yours ? "You  -  " : "") + "Level " + top.getLevel() + ", room " + top.getNumber(),
				Format.amount(p.xpPerHour(Planner.RESTART_TICKS)), yours ? Theme.GOLD_BRIGHT : view.level >= top.getLevel() ? Theme.GOLD : Theme.TEXT_FAINT));
		}
		ladder.add(rows, BorderLayout.CENTER);
		stack.add(ladder);

		if (!r.runs.isEmpty())
		{
			stack.add(new SectionHeader("Recent runs", Format.amount(r.totalXp) + " xp in all"));
			Card recent = new Card(new BorderLayout());
			StackPanel runRows = new StackPanel(4, 0);
			for (int i = r.runs.size() - 1; i >= 0 && i >= r.runs.size() - RECENT; i--)
			{
				Run run = r.runs.get(i);
				runRows.add(new RunRow(run, view.now));
			}
			recent.add(runRows, BorderLayout.CENTER);
			stack.add(recent);
		}
		replace(runs, stack);
	}

	private static JComponent line(String left, String right, Color color)
	{
		JPanel row = new JPanel(new BorderLayout(6, 0));
		row.setOpaque(false);
		JLabel l = Ui.label(left, Theme.small(), Theme.TEXT_MUTED);
		row.add(l, BorderLayout.CENTER);
		row.add(Ui.label(right, Theme.small(), color), BorderLayout.EAST);
		return row;
	}

	static Card note(String title, String text)
	{
		Card card = new Card(new BorderLayout(0, 4));
		card.accent(Theme.GOLD_DIM);
		card.add(Ui.label(title, Theme.body(), Theme.GOLD), BorderLayout.NORTH);
		card.add(Ui.wrapped(text, Theme.small(), Theme.TEXT_MUTED, WIDTH - 30), BorderLayout.CENTER);
		return card;
	}

	private static void replace(JScrollPane scroll, JComponent view)
	{
		int position = scroll.getVerticalScrollBar().getValue();
		scroll.setViewportView(view);
		scroll.revalidate();
		SwingUtilities.invokeLater(() -> scroll.getVerticalScrollBar().setValue(position));
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		g.setColor(Theme.INK);
		g.fillRect(0, 0, getWidth(), getHeight());
	}
}

package com.codex.plunder.ui;

import com.codex.plunder.core.Plan;
import com.codex.plunder.core.Room;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.Ellipse2D;
import javax.swing.JComponent;

/**
 * One room of the route: a numbered seal, the room's level, and what to do there. The room the
 * player stands in is ringed in teal; rooms walked straight through sit quietly; rooms the level
 * does not open yet are faded, with the level that opens them.
 */
class RoomRow extends JComponent
{
	private static final int HEIGHT = 34;

	private final Room room;
	private final Plan.Stop stop;
	private final boolean here;
	private final int locked;

	/** A room on the route. */
	RoomRow(Plan.Stop stop, boolean here)
	{
		this.room = stop.getRoom();
		this.stop = stop;
		this.here = here;
		this.locked = 0;
		init();
	}

	/** A room not open yet. */
	RoomRow(Room room)
	{
		this.room = room;
		this.stop = null;
		this.here = false;
		this.locked = room.getLevel();
		init();
	}

	private void init()
	{
		setOpaque(false);
		setPreferredSize(new Dimension(10, HEIGHT));
		setToolTipText("Room " + room.getNumber() + ": urns " + room.getUrnXp() + " xp, chest " + room.getChestXp()
			+ " xp, sceptre 1 in " + room.getSceptreOneIn());
	}

	static String work(Plan.Stop stop)
	{
		if (stop.isPassThrough())
		{
			return "Pass through";
		}
		StringBuilder text = new StringBuilder();
		if (stop.getUrns() > 0)
		{
			text.append(stop.getUrns()).append(stop.getUrns() == 1 ? " urn" : " urns");
		}
		if (stop.isChest())
		{
			text.append(text.length() > 0 ? " + " : "").append("chest");
		}
		if (stop.isSarcophagus())
		{
			text.append(text.length() > 0 ? " + " : "").append("sarc");
		}
		return text.toString();
	}

	private int xp()
	{
		return stop.getUrns() * room.getUrnXp() + (stop.isChest() ? room.getChestXp() : 0);
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		boolean pass = stop != null && stop.isPassThrough();
		Color seal = locked > 0 ? Theme.STROKE : pass ? Theme.GOLD_DIM : Theme.GOLD;

		if (here)
		{
			g.setColor(Theme.alpha(Theme.TEAL, 26));
			g.fillRoundRect(0, 1, w, h - 2, 8, 8);
		}

		// The seal: a gilt disc with the room's number.
		int d = 22;
		int sx = 4;
		int sy = (h - d) / 2;
		g.setPaint(new GradientPaint(0, sy, locked > 0 ? Theme.CARD_TOP : Theme.mix(seal, Color.WHITE, 0.2), 0, sy + d, locked > 0 ? Theme.CARD : Theme.mix(seal, Theme.INK_DEEP, 0.4)));
		g.fill(new Ellipse2D.Float(sx, sy, d, d));
		g.setStroke(new BasicStroke(here ? 1.6f : 1f));
		g.setColor(here ? Theme.TEAL : Theme.INK_DEEP);
		g.draw(new Ellipse2D.Float(sx + 0.5f, sy + 0.5f, d - 1, d - 1));
		g.setFont(Theme.title());
		FontMetrics bold = g.getFontMetrics();
		String n = String.valueOf(room.getNumber());
		g.setColor(locked > 0 ? Theme.TEXT_FAINT : Theme.INK_DEEP);
		g.drawString(n, sx + (d - bold.stringWidth(n)) / 2, sy + (d + bold.getAscent()) / 2 - 2);

		int tx = sx + d + 8;
		g.setFont(Theme.body());
		FontMetrics body = g.getFontMetrics();
		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		int top = h / 2 - 2;
		int bottom = h / 2 + small.getAscent() + 1;

		String right = locked > 0 ? "Opens at " + locked : pass ? "" : "+" + Format.amount(xp());
		int rw = small.stringWidth(right);
		g.setFont(Theme.body());
		String name = (locked > 0 ? "Room " + room.getNumber() : stop == null ? "" : work(stop));
		Color nameColor = locked > 0 ? Theme.TEXT_FAINT : pass ? Theme.TEXT_MUTED : Theme.TEXT;
		Ui.shadowed(g, Ui.clip(name, body, w - tx - rw - 12), tx, top, nameColor);
		g.setFont(Theme.small());
		boolean opening = stop != null && (stop.isSarcophagus() || stop.isChest());
		String odds = opening ? "1/" + room.getSceptreOneIn() : "";
		int oddsW = opening ? small.stringWidth(odds) + 8 : 0;
		String sub = locked > 0 ? room.getUrnXp() + " xp an urn" : here
			? "You are here" + (stop.getUrnsLeft() < room.getUrns() ? "  -  " + (room.getUrns() - stop.getUrnsLeft()) + " searched" : "")
			: "Level " + room.getLevel();
		g.setColor(here ? Theme.TEAL : Theme.TEXT_FAINT);
		g.drawString(Ui.clip(sub, small, w - tx - oddsW - 6), tx, bottom);
		if (!right.isEmpty())
		{
			g.setColor(locked > 0 ? Theme.TEXT_FAINT : Theme.GOLD);
			g.drawString(right, w - rw - 6, top);
		}
		if (opening)
		{
			g.setColor(Theme.alpha(Theme.TEAL, 200));
			g.drawString(odds, w - small.stringWidth(odds) - 6, bottom);
		}
		g.dispose();
	}
}

package com.codex.plunder.ui;

import com.codex.plunder.core.Run;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import javax.swing.JComponent;

/** One past run: how deep, what it paid, and when; a sceptre run is marked in teal. */
class RunRow extends JComponent
{
	private final Run run;
	private final long now;

	RunRow(Run run, long now)
	{
		this.run = run;
		this.now = now;
		setOpaque(false);
		setPreferredSize(new Dimension(10, 32));
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		g.setFont(Theme.body());
		FontMetrics body = g.getFontMetrics();
		int top = h / 2 - 2;
		int bottom = h / 2 + small.getAscent() + 1;
		int x = 0;
		if (run.isSceptre())
		{
			Sigil.paint(g, 0, (h - 16) / 2f, 16);
			x = 20;
		}
		String title = "+" + Format.amount(run.getThievingXp()) + " xp";
		Ui.shadowed(g, title, x, top, run.isSceptre() ? Theme.TEAL : Theme.GOLD);
		g.setFont(Theme.small());
		g.setColor(Theme.TEXT_MUTED);
		g.drawString("to room " + run.getDeepest(), x + body.stringWidth(title) + 6, top);
		String when = Format.ago(now - run.getAt());
		g.setColor(Theme.TEXT_FAINT);
		g.drawString(when, w - small.stringWidth(when), top);

		StringBuilder sub = new StringBuilder();
		sub.append(run.getUrns()).append(run.getUrns() == 1 ? " urn" : " urns");
		if (run.getChests() > 0)
		{
			sub.append(", ").append(run.getChests()).append(run.getChests() == 1 ? " chest" : " chests");
		}
		if (run.getSarcophagi() > 0)
		{
			sub.append(", ").append(run.getSarcophagi()).append(" sarc");
		}
		if (run.getArtefacts() > 0)
		{
			sub.append(", ").append(Format.coins(run.getArtefacts())).append(" gp");
		}
		if (run.isSceptre())
		{
			sub.insert(0, "Sceptre!  ");
		}
		g.setColor(run.isSceptre() ? Theme.TEAL : Theme.TEXT_FAINT);
		g.drawString(Ui.clip(sub.toString(), small, w - x - 40), x, bottom);
		String clock = Format.clock(run.getTicks());
		g.drawString(clock, w - small.stringWidth(clock), bottom);
		g.dispose();
	}
}

package com.codex.plunder.ui;

import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.Path2D;
import javax.swing.JComponent;

/** A small-caps heading with a gold diamond and a line that fades into the dark. */
public class SectionHeader extends JComponent
{
	private final String text;
	private final String trailing;

	public SectionHeader(String text)
	{
		this(text, null);
	}

	public SectionHeader(String text, String trailing)
	{
		this.text = text.toUpperCase();
		this.trailing = trailing;
		setFont(Theme.small());
		setPreferredSize(new Dimension(10, 20));
		setMinimumSize(new Dimension(10, 20));
		setMaximumSize(new Dimension(Integer.MAX_VALUE, 20));
		setAlignmentX(LEFT_ALIGNMENT);
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		g.setFont(getFont());
		paint(g, text, trailing, 0, 0, getWidth(), getHeight());
		g.dispose();
	}

	/** Draws a heading in a box; the card uses the same drawing. The font must already be set. */
	static void paint(Graphics2D g, String text, String trailing, int x, int y, int w, int h)
	{
		int mid = y + h / 2 + 2;
		Path2D diamond = new Path2D.Float();
		diamond.moveTo(x + 4, mid - 4);
		diamond.lineTo(x + 8, mid);
		diamond.lineTo(x + 4, mid + 4);
		diamond.lineTo(x, mid);
		diamond.closePath();
		g.setColor(Theme.GOLD);
		g.fill(diamond);

		FontMetrics fm = g.getFontMetrics();
		int textX = x + 13;
		int baseline = mid + fm.getAscent() / 2 - 1;
		g.setColor(Theme.GOLD);
		g.drawString(text, textX, baseline);

		int lineStart = textX + fm.stringWidth(text) + 6;
		int lineEnd = x + w;
		if (trailing != null && !trailing.isEmpty())
		{
			int tw = fm.stringWidth(trailing);
			lineEnd = x + w - tw - 6;
			g.setColor(Theme.TEXT_FAINT);
			g.drawString(trailing, x + w - tw, baseline);
		}
		if (lineEnd > lineStart)
		{
			g.setPaint(new GradientPaint(lineStart, 0, Theme.alpha(Theme.GOLD, 110), lineEnd, 0, Theme.alpha(Theme.GOLD, 0)));
			g.drawLine(lineStart, mid, lineEnd, mid);
		}
	}
}

package com.codex.plunder.ui;

import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.geom.RoundRectangle2D;
import java.util.function.IntConsumer;
import javax.swing.JComponent;

/**
 * Tabs drawn as one engraved strip: the chosen segment is lit from below by a
 * gold glow, the rest sit quietly in the ink.
 */
public class Segmented extends JComponent
{
	private final String[] labels;
	private final boolean large;
	private final Animator slide = new Animator(this);
	private int selected;
	private int hover = -1;
	private IntConsumer listener;

	public Segmented(boolean large, String... labels)
	{
		this.labels = labels;
		this.large = large;
		setFont(large ? Theme.title() : Theme.small());
		int h = large ? 28 : 22;
		setPreferredSize(new Dimension(10, h));
		setMinimumSize(new Dimension(10, h));
		setMaximumSize(new Dimension(Integer.MAX_VALUE, h));
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		MouseAdapter mouse = new MouseAdapter()
		{
			@Override
			public void mouseMoved(MouseEvent e)
			{
				int index = indexAt(e.getX());
				if (index != hover)
				{
					hover = index;
					repaint();
				}
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				hover = -1;
				repaint();
			}

			@Override
			public void mousePressed(MouseEvent e)
			{
				setSelected(indexAt(e.getX()), true);
			}
		};
		addMouseListener(mouse);
		addMouseMotionListener(mouse);
	}

	public void onChange(IntConsumer listener)
	{
		this.listener = listener;
	}

	public int getSelected()
	{
		return selected;
	}

	public void setSelected(int index, boolean notify)
	{
		if (index < 0 || index >= labels.length)
		{
			return;
		}
		boolean changed = index != selected;
		selected = index;
		slide.set(index, true);
		repaint();
		if (changed && notify && listener != null)
		{
			listener.accept(index);
		}
	}

	private int indexAt(int x)
	{
		int w = Math.max(1, getWidth());
		return Math.max(0, Math.min(labels.length - 1, x * labels.length / w));
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		float seg = w / (float) labels.length;

		RoundRectangle2D strip = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1, h - 1, 8, 8);
		g.setColor(Theme.INK_DEEP);
		g.fill(strip);

		float x = (float) (slide.get() * seg);
		RoundRectangle2D lit = new RoundRectangle2D.Float(x + 2, 2, seg - 4, h - 4, 6, 6);
		g.setPaint(new GradientPaint(0, 2, Theme.CARD_TOP, 0, h, Theme.mix(Theme.CARD_TOP, Theme.GOLD_DIM, 0.35)));
		g.fill(lit);
		g.setColor(Theme.alpha(Theme.GOLD, 120));
		g.draw(lit);
		g.setColor(Theme.GOLD_BRIGHT);
		g.fillRect(Math.round(x + seg * 0.3f), h - 4, Math.round(seg * 0.4f), 1);

		g.setFont(getFont());
		FontMetrics fm = g.getFontMetrics();
		for (int i = 0; i < labels.length; i++)
		{
			int tx = Math.round(i * seg + (seg - fm.stringWidth(labels[i])) / 2);
			int ty = (h + fm.getAscent()) / 2 - (large ? 2 : 1);
			java.awt.Color color = i == selected ? Theme.GOLD_BRIGHT : i == hover ? Theme.TEXT : Theme.TEXT_MUTED;
			Ui.shadowed(g, labels[i], tx, ty, color);
		}
		g.setColor(Theme.STROKE_SOFT);
		g.draw(strip);
		g.dispose();
	}
}

package com.codex.plunder.ui;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Path2D;
import java.awt.image.BufferedImage;

/**
 * The Pilot's mark: a stepped gilt pyramid under a desert sky, with the Pharaoh's sceptre
 * standing before it, its teal jewel catching the light.
 */
public final class Sigil
{
	private Sigil()
	{
	}

	public static BufferedImage icon(int size)
	{
		BufferedImage image = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		Theme.smooth(g);
		paint(g, 0, 0, size);
		g.dispose();
		return image;
	}

	/** Draws the mark in a size by size box. */
	public static void paint(Graphics2D g, float x, float y, float size)
	{
		float s = size / 16f;
		float stroke = Math.max(0.6f, 0.55f * s);

		// The pyramid: a lit face and a shadowed face meeting at the ridge.
		float apexX = x + 7.4f * s;
		float apexY = y + 1.6f * s;
		float baseY = y + 14.2f * s;
		float left = x + 0.6f * s;
		float right = x + 14.2f * s;
		float ridgeX = x + 8.8f * s;
		Path2D lit = new Path2D.Float();
		lit.moveTo(apexX, apexY);
		lit.lineTo(ridgeX, baseY);
		lit.lineTo(left, baseY);
		lit.closePath();
		Path2D shade = new Path2D.Float();
		shade.moveTo(apexX, apexY);
		shade.lineTo(right, baseY);
		shade.lineTo(ridgeX, baseY);
		shade.closePath();
		g.setPaint(new GradientPaint(x, apexY, Theme.GOLD_BRIGHT, x, baseY, Theme.GOLD));
		g.fill(lit);
		g.setPaint(new GradientPaint(x, apexY, Theme.mix(Theme.GOLD, Theme.GOLD_DIM, 0.4f), x, baseY, Theme.mix(Theme.GOLD_DIM, Theme.INK_DEEP, 0.45f)));
		g.fill(shade);

		// Courses of stone across both faces.
		g.setStroke(new BasicStroke(Math.max(0.5f, 0.4f * s)));
		g.setColor(Theme.alpha(Theme.INK_DEEP, 120));
		for (int i = 1; i <= 3; i++)
		{
			float t = i / 4f;
			float cy = apexY + (baseY - apexY) * t;
			float lx = apexX + (left - apexX) * t;
			float rx = apexX + (right - apexX) * t;
			g.drawLine(Math.round(lx), Math.round(cy), Math.round(rx), Math.round(cy));
		}
		// The doorway at the foot of the lit face.
		g.setColor(Theme.alpha(Theme.INK_DEEP, 200));
		g.fillRect(Math.round(x + 4.8f * s), Math.round(y + 11.2f * s), Math.max(1, Math.round(1.6f * s)), Math.round(3f * s));

		Path2D outline = new Path2D.Float();
		outline.moveTo(apexX, apexY);
		outline.lineTo(right, baseY);
		outline.lineTo(left, baseY);
		outline.closePath();
		g.setStroke(new BasicStroke(stroke));
		g.setColor(Theme.INK_DEEP);
		g.draw(outline);

		// The sceptre: a gilt staff with a teal jewel, standing in front of the shadowed face.
		float sx = x + 12.2f * s;
		float top = y + 5.6f * s;
		g.setStroke(new BasicStroke(Math.max(1.8f, 2.0f * s), BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.setColor(Theme.INK_DEEP);
		g.drawLine(Math.round(sx), Math.round(top + 2f * s), Math.round(sx), Math.round(y + 15.4f * s));
		g.setStroke(new BasicStroke(Math.max(0.9f, 0.9f * s), BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.setPaint(new GradientPaint(sx, top, Theme.GOLD_BRIGHT, sx, y + 15 * s, Theme.GOLD_DIM));
		g.drawLine(Math.round(sx), Math.round(top + 2f * s), Math.round(sx), Math.round(y + 15f * s));
		float r = 2.1f * s;
		Ellipse2D jewel = new Ellipse2D.Float(sx - r, top - r, r * 2, r * 2);
		g.setColor(Theme.INK_DEEP);
		g.setStroke(new BasicStroke(Math.max(1.2f, 1.2f * s)));
		g.draw(jewel);
		g.setPaint(new GradientPaint(sx, top - r, Theme.mix(Theme.TEAL, Theme.TEXT, 0.4f), sx, top + r, Theme.mix(Theme.TEAL, Theme.INK_DEEP, 0.3f)));
		g.fill(jewel);
		g.setColor(new Color(255, 255, 255, 160));
		g.fill(new Ellipse2D.Float(sx - r * 0.55f, top - r * 0.6f, r * 0.6f, r * 0.6f));
	}
}

package com.codex.plunder.ui;

import java.awt.Component;
import java.awt.Container;
import java.awt.Dimension;
import java.awt.Insets;
import java.awt.LayoutManager;
import java.awt.Rectangle;
import javax.swing.JPanel;
import javax.swing.Scrollable;
import javax.swing.border.EmptyBorder;

/**
 * A vertical stack where every child spans the full width at its preferred height.
 * It tracks the viewport width so nothing ever scrolls sideways in the side panel.
 */
public class StackPanel extends JPanel implements Scrollable
{
	public StackPanel(int gap, int pad)
	{
		super(new StackLayout(gap));
		setOpaque(false);
		setBorder(new EmptyBorder(pad, pad, pad, pad));
	}

	public StackPanel space(int height)
	{
		JPanel spacer = new JPanel();
		spacer.setOpaque(false);
		spacer.setPreferredSize(new Dimension(1, height));
		add(spacer);
		return this;
	}

	@Override
	public Dimension getPreferredScrollableViewportSize()
	{
		return getPreferredSize();
	}

	@Override
	public int getScrollableUnitIncrement(Rectangle visibleRect, int orientation, int direction)
	{
		return 16;
	}

	@Override
	public int getScrollableBlockIncrement(Rectangle visibleRect, int orientation, int direction)
	{
		return Math.max(16, visibleRect.height - 32);
	}

	@Override
	public boolean getScrollableTracksViewportWidth()
	{
		return true;
	}

	@Override
	public boolean getScrollableTracksViewportHeight()
	{
		return false;
	}

	static final class StackLayout implements LayoutManager
	{
		private final int gap;

		StackLayout(int gap)
		{
			this.gap = gap;
		}

		@Override
		public void addLayoutComponent(String name, Component comp)
		{
		}

		@Override
		public void removeLayoutComponent(Component comp)
		{
		}

		@Override
		public Dimension preferredLayoutSize(Container parent)
		{
			Insets in = parent.getInsets();
			int width = 0;
			int height = 0;
			int visible = 0;
			for (Component c : parent.getComponents())
			{
				if (!c.isVisible())
				{
					continue;
				}
				Dimension d = c.getPreferredSize();
				width = Math.max(width, d.width);
				height += d.height;
				visible++;
			}
			height += Math.max(0, visible - 1) * gap;
			return new Dimension(width + in.left + in.right, height + in.top + in.bottom);
		}

		@Override
		public Dimension minimumLayoutSize(Container parent)
		{
			return preferredLayoutSize(parent);
		}

		@Override
		public void layoutContainer(Container parent)
		{
			Insets in = parent.getInsets();
			int width = parent.getWidth() - in.left - in.right;
			int y = in.top;
			for (Component c : parent.getComponents())
			{
				if (!c.isVisible())
				{
					continue;
				}
				int h = c.getPreferredSize().height;
				c.setBounds(in.left, y, width, h);
				y += h + gap;
			}
		}
	}
}

package com.codex.plunder.ui;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.RoundRectangle2D;
import javax.swing.JComponent;

/** A small engraved tablet: a big number, its label, and a quiet line of context. */
class StatTile extends JComponent
{
	private final String value;
	private final String label;
	private final String note;
	private final Color color;

	StatTile(String value, String label, String note, Color color)
	{
		this.value = value;
		this.label = label;
		this.note = note;
		this.color = color;
		setPreferredSize(new Dimension(10, 54));
		setOpaque(false);
		setToolTipText(note == null || note.isEmpty() ? label : label + ": " + note);
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		paint(g, value, label, note, color, 0, 0, getWidth(), getHeight());
		g.dispose();
	}

	/** Draws a tablet in a box; the card uses the same drawing. */
	static void paint(Graphics2D g, String value, String label, String note, Color color, int x, int y, int w, int h)
	{
		RoundRectangle2D shape = new RoundRectangle2D.Float(x + 0.5f, y + 0.5f, w - 1, h - 1, Theme.RADIUS, Theme.RADIUS);
		g.setPaint(new GradientPaint(x, y, Theme.CARD_TOP, x, y + h, Theme.CARD));
		g.fill(shape);
		g.setColor(Theme.STROKE_SOFT);
		g.draw(shape);
		g.setColor(Theme.alpha(color, 160));
		g.fillRect(x + Theme.RADIUS, y + 1, w - Theme.RADIUS * 2, 1);

		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		g.setColor(Theme.TEXT_MUTED);
		g.drawString(label.toUpperCase(), x + 8, y + 6 + small.getAscent());

		g.setFont(Theme.title());
		FontMetrics bold = g.getFontMetrics();
		Ui.shadowed(g, Ui.clip(value, bold, w - 16), x + 8, y + 8 + small.getHeight() + bold.getAscent(), color);
		if (note != null && !note.isEmpty())
		{
			g.setFont(Theme.small());
			g.setColor(Theme.TEXT_FAINT);
			g.drawString(Ui.clip(note, small, w - 16), x + 8, y + h - 6);
		}
	}
}

package com.codex.plunder.ui;

import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import net.runelite.client.ui.FontManager;

/**
 * The Codex look: warm ink, aged gold and a single arcane teal, drawn with the
 * game's own fonts so the panel reads as part of Gielinor rather than a web page.
 * The Pilot keeps gold for what is worth doing, teal for the sceptre and its odds, and turns
 * ember then blood as the clock runs down, so the colour says how urgent a thing is before it is read.
 */
public final class Theme
{
	public static final Color INK = new Color(23, 20, 16);
	public static final Color INK_DEEP = new Color(16, 14, 11);
	public static final Color CARD = new Color(34, 30, 24);
	public static final Color CARD_TOP = new Color(42, 37, 29);
	public static final Color CARD_HOVER = new Color(48, 42, 33);
	public static final Color STROKE = new Color(66, 56, 42);
	public static final Color STROKE_SOFT = new Color(48, 41, 32);

	public static final Color GOLD = new Color(214, 178, 106);
	public static final Color GOLD_BRIGHT = new Color(246, 214, 144);
	public static final Color GOLD_DIM = new Color(132, 108, 66);
	public static final Color TEAL = new Color(96, 184, 170);
	public static final Color GREEN = new Color(130, 196, 108);
	public static final Color EMBER = new Color(222, 134, 86);
	public static final Color BLOCKED = new Color(176, 92, 84);
	public static final Color BLOOD = new Color(204, 70, 60);
	public static final Color BLOOD_DEEP = new Color(120, 32, 28);
	public static final Color VIOLET = new Color(176, 132, 222);

	public static final Color TEXT = new Color(234, 224, 202);
	public static final Color TEXT_MUTED = new Color(160, 148, 126);
	public static final Color TEXT_FAINT = new Color(110, 100, 84);

	public static final int RADIUS = 10;
	public static final int GUTTER = 8;

	private Theme()
	{
	}

	public static Font title()
	{
		return FontManager.getRunescapeBoldFont();
	}

	public static Font body()
	{
		return FontManager.getRunescapeFont();
	}

	public static Font small()
	{
		return FontManager.getRunescapeSmallFont();
	}

	public static Color alpha(Color c, int alpha)
	{
		return new Color(c.getRed(), c.getGreen(), c.getBlue(), alpha);
	}

	public static Color mix(Color a, Color b, double t)
	{
		t = Math.max(0, Math.min(1, t));
		return new Color(
			(int) Math.round(a.getRed() + (b.getRed() - a.getRed()) * t),
			(int) Math.round(a.getGreen() + (b.getGreen() - a.getGreen()) * t),
			(int) Math.round(a.getBlue() + (b.getBlue() - a.getBlue()) * t),
			(int) Math.round(a.getAlpha() + (b.getAlpha() - a.getAlpha()) * t));
	}

	/** Progress colour: ember when just begun, gold through the middle, green when nearly there. */
	public static Color progressColor(double progress)
	{
		if (progress >= 1)
		{
			return GREEN;
		}
		if (progress < 0.5)
		{
			return mix(EMBER, GOLD, progress * 2);
		}
		return mix(GOLD, TEAL, (progress - 0.5) * 2);
	}

	/** The clock as a colour: gold with time in hand, ember under ninety seconds, blood under thirty. */
	public static Color clock(int ticksLeft)
	{
		if (ticksLeft <= 50)
		{
			return BLOOD;
		}
		if (ticksLeft <= 150)
		{
			return EMBER;
		}
		return GOLD;
	}

	/** Smooth shapes, but the pixel fonts stay crisp. */
	public static void smooth(Graphics2D g)
	{
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);
		g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
	}
}

package com.codex.plunder.ui;

import java.awt.Color;
import java.awt.Component;
import java.awt.Container;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.event.MouseAdapter;
import javax.swing.JLabel;

/** Small helpers shared by the panel's components. */
public final class Ui
{
	private Ui()
	{
	}

	public static JLabel label(String text, Font font, Color color)
	{
		JLabel label = new JLabel(text);
		label.setFont(font);
		label.setForeground(color);
		return label;
	}

	/**
	 * A label that wraps inside the side panel's narrow width. Swing's HTML renderer
	 * treats CSS pixels as points, so the width is converted to keep it in screen pixels.
	 */
	public static JLabel wrapped(String text, Font font, Color color, int width)
	{
		int css = Math.round(width * 0.75f);
		return label("<html><div style='width:" + css + "px'>" + escape(text) + "</div></html>", font, color);
	}

	public static String escape(String text)
	{
		return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}

	/** Lets a clickable card keep its hover and click while the pointer is over its children. */
	static void forwardMouse(Container root, MouseAdapter adapter)
	{
		for (Component child : root.getComponents())
		{
			child.addMouseListener(adapter);
			if (child instanceof Container)
			{
				forwardMouse((Container) child, adapter);
			}
		}
	}

	/** Text with the one pixel black shadow the game puts under its own lettering. */
	public static void shadowed(Graphics2D g, String text, int x, int y, Color color)
	{
		g.setColor(Color.BLACK);
		g.drawString(text, x + 1, y + 1);
		g.setColor(color);
		g.drawString(text, x, y);
	}

	/** Cuts text to fit a width, ending it with an ellipsis. */
	public static String clip(String text, java.awt.FontMetrics fm, int width)
	{
		if (text == null)
		{
			return "";
		}
		if (fm.stringWidth(text) <= width)
		{
			return text;
		}
		int end = text.length();
		while (end > 0 && fm.stringWidth(text.substring(0, end) + "...") > width)
		{
			end--;
		}
		return text.substring(0, end) + "...";
	}
}

package com.codex.plunder.ui;

import com.codex.plunder.core.Check;
import com.codex.plunder.core.Goal;
import com.codex.plunder.core.Plan;
import com.codex.plunder.core.Room;
import com.codex.plunder.core.Run;
import com.codex.plunder.core.Step;
import java.util.Collections;
import java.util.List;

/** Everything the panel shows, worked out on the client thread and handed over whole. */
public final class View
{
	/** What the panel has to show. */
	public enum State
	{
		LOGGED_OUT,
		TOO_LOW,
		READY
	}

	/** Totals for the account, kept apart from the run in hand. */
	public static final class Record
	{
		final List<Run> runs;
		final long[] opened;
		final int sceptres;
		final long totalRuns;
		final long totalXp;
		final long totalArtefacts;
		final int recentRate;
		final int paceSamples;

		public Record(List<Run> runs, long[] opened, int sceptres, long totalRuns, long totalXp, long totalArtefacts, int recentRate, int paceSamples)
		{
			this.runs = runs == null ? Collections.emptyList() : runs;
			this.opened = opened == null ? new long[Room.values().length] : opened;
			this.sceptres = sceptres;
			this.totalRuns = totalRuns;
			this.totalXp = totalXp;
			this.totalArtefacts = totalArtefacts;
			this.recentRate = recentRate;
			this.paceSamples = paceSamples;
		}

		static Record empty()
		{
			return new Record(null, null, 0, 0, 0, 0, 0, 0);
		}
	}

	/** The run in hand. */
	public static final class Live
	{
		final int ticksLeft;
		final int thievingXp;
		final long artefacts;
		final int opened;
		final double sceptreSoFar;

		public Live(int ticksLeft, int thievingXp, long artefacts, int opened, double sceptreSoFar)
		{
			this.ticksLeft = ticksLeft;
			this.thievingXp = thievingXp;
			this.artefacts = artefacts;
			this.opened = opened;
			this.sceptreSoFar = sceptreSoFar;
		}
	}

	/** The ready check and what the pack holds, while logged in. */
	public static final class Ready
	{
		final List<Check> checks;
		final int artefacts;
		final long artefactValue;

		public Ready(List<Check> checks, int artefacts, long artefactValue)
		{
			this.checks = checks == null ? Collections.emptyList() : checks;
			this.artefacts = artefacts;
			this.artefactValue = artefactValue;
		}
	}

	final State state;
	final String player;
	final int level;
	final long xp;
	final int targetLevel;
	final Goal goal;
	/** The rest of the run in hand, or a fresh run's plan outside the pyramid. */
	final Plan plan;
	/** A whole fresh run at this level and goal, for per-run figures. */
	final Plan fresh;
	/** A fresh run at each room's entry level, for the ladder. */
	final List<Plan> ladder;
	final Step step;
	final Live live;
	final Record record;
	final long now;
	Ready ready;

	public View(State state, String player, int level, long xp, int targetLevel, Goal goal, Plan plan, Plan fresh,
		List<Plan> ladder, Step step, Live live, Record record, long now)
	{
		this.state = state;
		this.player = player;
		this.level = level;
		this.xp = xp;
		this.targetLevel = targetLevel;
		this.goal = goal == null ? Goal.EXPERIENCE : goal;
		this.plan = plan;
		this.fresh = fresh;
		this.ladder = ladder == null ? Collections.emptyList() : ladder;
		this.step = step;
		this.live = live;
		this.record = record == null ? Record.empty() : record;
		this.now = now;
	}

	public View ready(Ready ready)
	{
		this.ready = ready;
		return this;
	}

	public static View loggedOut()
	{
		return new View(State.LOGGED_OUT, null, 0, 0, 99, Goal.EXPERIENCE, null, null, null, null, null, null, System.currentTimeMillis());
	}

	boolean inRun()
	{
		return live != null;
	}
}

package com.codex.plunder.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class PlannerTest
{
	private final Pace pace = new Pace();

	@Test
	public void roomsOpenEveryTenLevels()
	{
		assertNull(Room.highest(20));
		assertEquals(Room.ONE, Room.highest(21));
		assertEquals(Room.FOUR, Room.highest(60));
		assertEquals(Room.EIGHT, Room.highest(99));
		assertEquals(61, Room.nextUnlock(55));
		assertEquals(0, Room.nextUnlock(91));
	}

	@Test
	public void deepRoomsGetTheUrnsAndShallowRoomsArePassed()
	{
		Plan plan = Planner.fresh(91, Goal.EXPERIENCE, pace);
		assertEquals(Room.EIGHT, plan.getTop());
		assertEquals(8, plan.getStops().size());
		assertEquals(13, plan.stop(Room.EIGHT).getUrns());
		assertEquals(13, plan.stop(Room.SEVEN).getUrns());
		assertTrue(plan.stop(Room.ONE).isPassThrough());
		assertTrue(plan.stop(Room.TWO).isPassThrough());
		// Chests from room four on are cheap and always taken.
		for (Room r : new Room[]{Room.FOUR, Room.FIVE, Room.SIX, Room.SEVEN, Room.EIGHT})
		{
			assertTrue(r.name(), plan.stop(r).isChest());
		}
		assertFalse(plan.stop(Room.EIGHT).isSarcophagus());
		assertTrue(plan.getTicksNeeded() <= Planner.RUN_TICKS);
		// Roughly the quarter million an hour the wiki gives for 91.
		int rate = plan.xpPerHour(Planner.RESTART_TICKS);
		assertTrue("rate " + rate, rate > 200_000 && rate < 320_000);
	}

	@Test
	public void lowLevelsLootEverythingAndLeaveEarly()
	{
		Plan plan = Planner.fresh(25, Goal.EXPERIENCE, pace);
		assertEquals(1, plan.getStops().size());
		Plan.Stop only = plan.current();
		assertEquals(13, only.getUrns());
		assertTrue(only.isChest());
		assertTrue(plan.spare() > 100);
	}

	@Test
	public void sceptreHuntersOpenChestsAndSarcophagiFirst()
	{
		Plan plan = Planner.fresh(91, Goal.SCEPTRE, pace);
		for (Room r : Room.values())
		{
			assertTrue(r.name(), plan.stop(r).isChest());
			assertEquals(r.name(), r.getNumber() >= 4, plan.stop(r).isSarcophagus());
		}
		Plan xp = Planner.fresh(91, Goal.EXPERIENCE, pace);
		assertTrue(plan.getSceptreChance() > xp.getSceptreChance());
		// The wiki's figure for every chest and the deep sarcophagi at 91 is about 1 in 69.
		assertEquals(1 / 69.0, plan.getSceptreChance(), 0.002);
	}

	@Test
	public void aSlowRunShortensWhatFollows()
	{
		Here inSeven = new Here(Room.SEVEN, 13, false, false, true);
		Plan plenty = Planner.plan(91, Goal.EXPERIENCE, pace, inSeven, 300);
		Plan short_ = Planner.plan(91, Goal.EXPERIENCE, pace, inSeven, 120);
		assertEquals(13, plenty.stop(Room.EIGHT).getUrns());
		int urns = short_.stop(Room.SEVEN).getUrns() + short_.stop(Room.EIGHT).getUrns();
		assertTrue(urns < 13);
		// Room eight's urns pay more, so they are kept over room seven's.
		assertTrue(short_.stop(Room.EIGHT).getUrns() >= short_.stop(Room.SEVEN).getUrns());
		assertTrue(short_.getTicksNeeded() <= 120);
	}

	@Test
	public void searchedUrnsAreNotPlannedAgain()
	{
		Here half = new Here(Room.EIGHT, 5, true, false, true);
		Plan plan = Planner.plan(95, Goal.EXPERIENCE, pace, half, 400);
		assertEquals(5, plan.current().getUrns());
		assertFalse(plan.current().isChest());
		assertTrue(plan.current().isChestOpen());
	}

	@Test
	public void oddsAddUpAcrossRooms()
	{
		long[] opened = new long[8];
		opened[7] = 650;
		assertEquals(1.0, Odds.expected(opened), 1e-9);
		assertEquals(1 - Math.pow(1 - 1 / 650.0, 650), Odds.atLeastOne(opened), 1e-9);
		assertEquals(Math.exp(-1) / 2, Odds.luck(opened, 0), 1e-9);
		assertTrue(Odds.luck(opened, 2) > 0.8);
		assertEquals(451, Odds.runsFor(1 / 650.0, 0.5));
	}

	@Test
	public void paceLearnsFromRuns()
	{
		Pace p = new Pace();
		for (int i = 0; i < Pace.TRUSTED; i++)
		{
			p.urnTook(7);
		}
		assertEquals(7, p.urn(), 1e-9);
		p.urnTook(500);
		assertEquals(7, p.urn(), 1e-9);
	}

	@Test
	public void aRunIsFollowedRoomByRoom()
	{
		Pace p = new Pace();
		RunTracker t = new RunTracker();
		t.begin(0, 0, Goal.EXPERIENCE);
		t.room(Room.SEVEN, 0, p);
		t.urnSearched(10, p);
		t.urnSearched(18, p);
		t.chestOpened(25);
		t.thieving(675 * 2 + 450);
		t.room(Room.EIGHT, 45, p);
		t.sarcophagusOpened(60);
		t.strength(275);
		Run run = t.finish(100);
		assertEquals(8, run.getDeepest());
		assertEquals(2, run.getUrns());
		assertEquals(1, run.getChests());
		assertEquals(1, run.getSarcophagi());
		assertEquals(1 - (1 - 1 / 650.0) * (1 - 1 / 650.0), run.getSceptreChance(), 1e-9);
		assertEquals(1, p.getUrnSamples());
		assertEquals(1, p.getPassSamples());

		Logbook book = new Logbook();
		book.record(run, t.getOpened());
		assertEquals(2, book.openedTotal());
		assertEquals(1, book.getTotalRuns());
	}

	@Test
	public void theExperienceTableMatchesTheGame()
	{
		assertEquals(0, Levels.xpFor(1));
		assertEquals(83, Levels.xpFor(2));
		assertEquals(13_034_431, Levels.xpFor(99));
		assertEquals(91, Levels.levelFor(5_902_831));
	}
}

package com.codex.plunder.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import java.util.Arrays;
import java.util.List;
import org.junit.Test;

public class ReadyTest
{
	@Test
	public void theRouteWalksTheRoomOnceWithoutCrossingBack()
	{
		// Two rows of urns; nearest-first alone would zigzag between them.
		int[] xs = {0, 4, 8, 12, 0, 4, 8, 12};
		int[] ys = {0, 0, 0, 0, 6, 6, 6, 6};
		List<Integer> path = Route.order(0, 3, xs, ys, 8);
		assertEquals(8, path.size());
		assertEquals(8, path.stream().distinct().count());
		// One row there and the other back is 12 + 6 + 12 = 30 steps plus the 3 to reach the first.
		assertTrue("length " + Route.length(0, 3, xs, ys, path), Route.length(0, 3, xs, ys, path) <= 33);
	}

	@Test
	public void aShortPlanTakesTheNearestUrns()
	{
		int[] xs = {1, 2, 30, 31};
		int[] ys = {0, 0, 0, 0};
		List<Integer> path = Route.order(0, 0, xs, ys, 2);
		assertEquals(Arrays.asList(0, 1), path);
	}

	@Test
	public void theReadyCheckWarnsOfAFullPackAndLowHitpoints()
	{
		Plan plan = Planner.fresh(40, Goal.EXPERIENCE, new Pace());
		List<Check> checks = Check.ready(new Check.Kit(40, 10, 8, 2, false, false), plan, 6);
		assertEquals(Check.State.WARN, checks.get(0).getState());
		assertTrue(checks.stream().anyMatch(c -> c.getTitle().equals("Low hitpoints")));
		assertTrue(checks.stream().anyMatch(c -> c.getTitle().equals("Bring a snake charm")));
		assertTrue(checks.stream().anyMatch(c -> c.getTitle().equals("Bring a lockpick")));

		Plan high = Planner.fresh(91, Goal.EXPERIENCE, new Pace());
		List<Check> late = Check.ready(new Check.Kit(91, 70, 99, 20, true, true), high, 8);
		assertEquals(Check.State.GOOD, late.get(0).getState());
		assertTrue(late.stream().anyMatch(c -> c.getTitle().equals("Leave the snake charm")));
		assertTrue(late.stream().anyMatch(c -> c.getTitle().equals("Leave the lockpick")));
		assertTrue(late.stream().anyMatch(c -> c.getTitle().equals("Protect from Melee")));
	}

	@Test
	public void dangerComesBeforeThePlan()
	{
		Plan plan = Planner.plan(91, Goal.EXPERIENCE, new Pace(), new Here(Room.EIGHT, 13, false, false, true), 300);
		assertEquals(Step.Kind.URNS, Step.next(plan, true, false, 0).getKind());
		Step chased = Step.next(plan, true, false, 0, new Step.Alarm(false, false, true, true));
		assertEquals("Protect from Melee", chased.getTitle());
		assertEquals(Step.Kind.DANGER, Step.next(plan, true, false, 0, new Step.Alarm(true, false, false, false)).getKind());
		assertEquals("Eat first", Step.next(plan, true, false, 0, new Step.Alarm(true, true, false, false)).getTitle());
	}

	@Test
	public void slotsComeFromRecentRunsOnceThereAreThree()
	{
		Logbook book = new Logbook();
		Plan plan = Planner.fresh(91, Goal.EXPERIENCE, new Pace());
		assertTrue(book.slotsNeeded(plan, 10) > 0);
		for (int i = 0; i < 3; i++)
		{
			RunTracker t = new RunTracker();
			t.begin(0, 0, Goal.EXPERIENCE);
			t.room(Room.EIGHT, 0, null);
			t.urnSearched(5, null);
			t.artefacts(4 + i, 1000);
			book.record(t.finish(100), t.getOpened());
		}
		assertEquals(6, book.slotsNeeded(plan, 10));
	}
}
